arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>" -d "types=public_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d.get('error')); sys.exit()
for c in d['channels']:
    if 'launch' in c['name'].lower() or 'ops' in c['name'].lower():
        print(c['id'], c['name'], c.get('topic',''))
"

