arguments.command:
curl -s -X POST "https://slack.com/api/users.list?token=<TOKEN>" -d "limit=0" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d.get('error')); sys.exit()
for u in d['members']:
    name=(u.get('real_name') or '')
    if 'diego' in name.lower() or 'alvarez' in name.lower() or 'moral' in name.lower():
        print(u['id'], '->', name, '|', u.get('profile',{}).get('display_name'))
"

